class Power(ABC):
    @abstractmethod
    def activate(self) -> None: ...                     # the sandbox method
    def _play_sound(self, sound: int, volume: float = 1.0) -> None: ...      # primitives
    def _spawn_particles(self, kind: int, count: int) -> None: ...

class SkyLaunch(Power):
    def activate(self) -> None:                         # composes primitives only
        self._play_sound(SOUND_SPROING)
        self._spawn_particles(PARTICLE_DUST, 10)
        self._move(0, 0, 20)
